    } else if (!valid) { r = 'wrong'; wrong++; }
    else if (p === g || (gold[`${f}_alt`] || []).includes(p)) { r = 'right'; right++; }
    else if (p === 'not_visible') { r = 'abstained'; abstained++; wrong++; }
