function checkListing(out, ranges, fallbackCurrency, text) {
  if (!out || typeof out !== 'object') return { fields: out, issues: [], changed: [] };
  const f = JSON.parse(JSON.stringify(out));
  const issues = [];
  const changed = [];
  const R = ranges || {};
